class AtUe(LteUe):
    """At Ue Common"""

    data_transfer_types = {
        # tool   implementing class
        'iperf': AtIperfUeDataTransfer,
        'iperf_uepc': AtIperfUePcDataTransfer,
        'icmp': AtDataTransferIcmp,
        'icmp_uepc': AtDataTransferIcmp,
    }

    # pylint: disable=too-many-instance-attributes, broad-except, unnecessary-pass
    def __init__(self, name, ue_pc, ue_config, prefix="COM"):
        """
        :param name: UE name from config.yml
        :param ue_pc: taf.ue.rpc.jsonrpc.Rpc object
        :param ue_config: UE configuration from config.yml, everything under CONSTRUCTOR_PARAMETERS key
        :param prefix: communication prefix
        """
        self.ue_config_full = ue_config
        self.configuration = ue_config["configuration"]

        super().__init__(name, self.configuration)

        self.prepared = False
        self.ne_id = None
        self.ue_pc = ue_pc
        self.ue_pc_ip = self.configuration["ue_pc_address"]
        self.ue_com_port = f'{prefix}{ue_config["com_port"]}'
        self.ue_id = f'{self.ue_pc_ip}:{self.ue_com_port}'

        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {
            'area': 'UE',
            'ue_id': self.ue_id})

        self._create_ue_identification()
        self._sub_access = None

    def _create_ue_identification(self):
        ue_identification = f'{self.ue_pc_ip}:{self.ue_com_port}'
        self.ne_id = UeIdentification(identifiers=[('at', ue_identification)],
                                      network_elem_type='UE',
                                      specific_for_tool='at')

    def __str__(self):
        return f"{self.__class__.__name__}({self.name if hasattr(self, 'name') else ''})"

    def __repr__(self):
        return f"{self.__class__.__name__}({self.name if hasattr(self, 'name') else ''}, at {hex(id(self))})"

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        self.logger.debug("checking whether UE can be reserved on taf.ue.proxy")
        reserved_ues = self.ue_pc.get_reserved_ues().get("ue_ids", [])
        self.logger.debug(f"list of already reserved UEs on taf.ue.proxy: {reserved_ues}")
        if self.ue_com_port in reserved_ues:
            raise UeAlreadyReserved(
                f"UE with serial number \"{self.ue_com_port}\" cannot be reserved, because is already reserved. "
                f"The reservation could be made manually or by previous Robot TC.\n"
                f"Before re-execution:\n"
                f"1) make sure that UE PC isn't used by other tester or Robot TC AND\n"
                f"2) repair the environment:\n"
                f"  a) restart taf.ue.proxy service OR\n"
                f"  b) release UE manually: open \"{self.ue_pc.remote_url}/docs\" -> open \"release_ue\" endpoint "
                f"-> button \"Try it out\" -> provide ue_id \"{self.ue_com_port}\" in request body -> button \"Execute\"")
        self.logger.debug("prepare_ue before calling reserve_ue on taf.ue.proxy")
        self.prepared = self.ue_pc.reserve_ue(ue_id=self.ue_com_port, ue_config={
            'serial_number': self.ue_config_full.get("serial_number", None),
            'sub_access': self.ue_config_full.get("sub_access", None),
            'dt_from_uepc': self.configuration.get('data_transfer', {}).get('iperf', {}).get('dt_from_uepc', None),
            'access': self.ue_config_full.get("access", None),
        })
        self._sub_access = self.prepared if self.prepared != "At" else None

        sub_access_postfix = f' sub-access: {self._sub_access}' \
            if self._sub_access else ""
        self.logger.debug(f"prepare_ue after calling reserve_ue on taf.ue.proxy{sub_access_postfix}")
        self._log_ue_pc_diagnostic_info()
        return self.prepared

    def shutdown(self):
        """
        Release reserved UE
        :return: None
        """
        self.logger.debug("executing shutdown")
        self.ue_pc.release_ue(ue_id=self.ue_com_port)

    def attach(self, timeout=-1, validation=True, top_cmd_only=False, **kwargs):
        """
        Perform attach on UE.

        :param timeout: not supported
        :param validation: if True, check if attach state was changed successfully
                              and raise CannotAttachError exception if not; turned on by default
        :param top_cmd_only: if True:
                                - performs the AT command to attach UE
                                - performs attach using QMI Test Pro (if use_qmi==True)
                             if False:
                                - performs the AT command to enable echo
                                - performs the AT command to set full functionality level (if attach_via_fun_lev==False)
                                - waits if a previous attach attempt fails and performs the AT command to detach UE
                                - performs the AT command to attach UE
                                - performs attach using QMI Test Pro (if use_qmi==True)
                                - performs the AT command for cell registration
        :param kwargs: UE specific arguments for attach, e.g.:
                       - use_qmi: if True, QMI is used (UE need to have configured `qmi_path` and `qmi_device_name`)
                       - single_check: if True, there is only one attempt to check attach status (default: False)
                       - attach_via_fun_lev: bool, if True then attach will be done via SetFunctionalityLevel command (Quectel)
                       - apn: str, APN to use for MBIM attach (Quectel, Linux) (recommended to use)
                       - interface_name: str, network interface name to use for MBIM attach (Quectel, Linux) (default is 'wwan0')
        :return: None
        """
        self.logger.debug("executing attach")
        kwargs.update({
            'validation': bool(strtobool(validation) if isinstance(validation, str) else validation),
            'top_cmd_only': bool(strtobool(top_cmd_only) if isinstance(top_cmd_only, str) else top_cmd_only)
        })
        if "use_qmi" in kwargs.keys() and kwargs["use_qmi"] == 'True':
            kwargs.update({
                'qmi_path': self.configuration['qmi_path'],
                'qmi_device_name': self.configuration['qmi_device_name']
            })
        if "single_check" in kwargs.keys():  # For `single_check=True` there is one attempt to check attach status
            kwargs.update({'single_check': strtobool(str(kwargs["single_check"]))})

        response = self.ue_pc.attach_ue(ue_id=self.ue_com_port, extra_params=kwargs)
        self.log_ue_info(['manufacturer', 'model', 'imsi', 'imei'])
        self.logger.debug(f"attach response: {response}")

    def detach(self, timeout=-1, validation=True, top_cmd_only=False, **kwargs):
        """
        Perform detach on UE.

        :param timeout: not supported
        :param validation: if True, check if detach state was changed successfully
                              and raise an exception if not; turned on by default
        :param top_cmd_only: not supported
        :return: None
        """
        self.logger.debug("executing detach")
        kwargs.update({
            'validation': strtobool(validation) if isinstance(validation, str) else validation,
            'top_cmd_only': strtobool(top_cmd_only) if isinstance(top_cmd_only, str) else top_cmd_only
        })
        response = self.ue_pc.detach_ue(ue_id=self.ue_com_port, extra_params=kwargs)
        self.logger.debug(f"detach response: {response}")

    def log_ue_info(self, ue_params='ALL'):
        """
        Logs specified UE information

        :param ue_params: list of UE parameters to log or 'ALL' if all available parameters are required. Default: ALL.
        :return: None
        """
        response = self.get_info(ue_params)
        self.logger.debug(f"output from get_info: {response}")
        robot_logger.info(json.dumps(response, sort_keys=False, indent=4))

    def get_ue_info(self, ue_params='ALL'):
        """
        Returns specified UE information

        :param ue_params: UE parameters to return or 'ALL' if all available parameters are required. Default: ALL.
        :return: info
        """
        response = self.get_info(ue_params)
        self.logger.debug(f"output from get_info: {response}")
        response = list(response.values())[0] if len(response) == 1 else response
        return response

    def get_info(self, ue_params):
        self.logger.debug(f"executing get_info with parameters {ue_params}")
        if isinstance(ue_params, str):
            wanted_attrs = [ue_params.lower()]
        elif isinstance(ue_params, list):
            wanted_attrs = [info_type.lower() for info_type in ue_params if isinstance(info_type, str)]
        else:
            raise TypeError(f"`AtUe.get_info` - wrong `info` parameter type: {type(ue_params)}.\n"
                            f"Allowed types: str, list")

        if 'all' in wanted_attrs:
            response = self.ue_pc.get_ue_info(ue_id=self.ue_com_port)
            self.logger.info(json.dumps(response, sort_keys=False, indent=4))
            return response

        response = self.ue_pc.get_ue_info(ue_id=self.ue_com_port, ue_attributes=wanted_attrs)
        self.logger.info(json.dumps(response, sort_keys=False, indent=4))
        return response

    def get_ue_id(self):
        """
        Return ue id specific for used ue-implementation/tool.

        :return: tool specific ue id
        """
        return self.ue_id

    def reboot_ue(self, timeout=120):
        """
        Reboot UE and wait until it is fully functional
        :param timeout - waiting time in seconds for UE after reboot
        """
        self.logger.debug("Executing reboot ue")
        return self.ue_pc.reboot_ue(ue_id=self.ue_com_port, timeout=timeout)

