    def change_network_mode(self, network_mode_args, **kwargs):
        """
        Changes network mode of UE.

        Available network mode elements are:

        - for `AT`: `automatic`, `lte`, `wcdma`, `gsm`, `5g`, `LTE:5G`;
        - for `Quectel`: `AUTO`, `WCDMA`, `LTE`, `NR5G`;

        For Quectel UE is possible combinations of network modes, e.g.: `LTE:5G` (separated with `:`).

        :param network_mode_args: desired network mode
        :return:  None
        """
        network_mode = network_mode_args if isinstance(network_mode_args, str) else str(list(network_mode_args)[0])
        ue_type = self.__class__.__name__.lower()[:-2]  # names are AtUe or QuectelUe, [:-2] removes the 'Ue' part
        self.logger.debug("Executing Change Network Mode")
        self.ue_pc.change_network_mode(ue_id=self.ue_com_port, network_mode=network_mode.lower(), validation=False,
                                       configuration={"ue_type": ue_type})

    def set_active_bands(self, technology, bands):
        """
        Set active bands.

        AT command possible technologies:
         - WCDMA and accepted technology values:

           + for Quectel: `WCDMA`, `GW`
           + for Simcom: `WCDMA`
         - LTE and accepted technology values for Quectel and Simcom:

           + `LTE`
         - NR NSA and accepted technology values:

           + for Quectel: `5G_NSA`, `NR5G_NSA`, `NR_NSA`, `NSA_NR5G`, `NRNSA`
           + for Simcom: `NRNSA`
         - NR SA and accepted technology values:

           + for Quectel: `5G_SA`, `NR5G_SA`, `NR_SA`, `NR5G`, `NRSA`
           + for Simcom: `NRSA`
        Example robot Framework usage:
          | ``Set Active Bands    UE_1    WCDMA  1:3:7``
          | ``Set Active Bands    UE_1    LTE    3:7``
          | ``Set Active Bands    UE_1    NRNSA  7:8``
          | ``Set Active Bands    UE_1    NRSA   78``

        :param technology: Network mode in case of AT, like `LTE` or `NR5G`, or `WCDMA`, or `NRNSA`
        :type technology: str
        :param bands: band number(s)
        :type bands: str
        :return: None
        """
        bands = bands.split(':')
        ue_type = self.__class__.__name__.lower()[:-2]
        self.ue_pc.set_active_bands(ue_id=self.ue_com_port, technology=technology.upper(), identifier=0, bands=bands,
                                    extra_params={"ue_type": ue_type})

    def set_nr5g_mode(self, disable_mode):
        """
        Set the preference for disabling specific modes in 5G NR
        :param disable_mode: A string specifying the mode to disable:
                         - "SA": Disable SA mode
                         - "NSA": Disable NSA mode
                         - "NONE": Neither is disabled
        :return: None
        """
        ue_type = self.__class__.__name__.lower()[:-2]
        self.ue_pc.set_nr5g_mode(ue_id=self.ue_com_port, disable_mode=disable_mode,
                                 extra_params={"ue_type": ue_type})

    def set_earfcn_lock(self, network_mode, earfcn, scs=0, **kwargs):
        """
        Quectel / Simcom: Lock EARFCN.
        :param network_mode: Network mode for which to lock the earfcn
        :param earfcn: EARFCN number, for '0' than disable EARFCN lock
        :param scs: SCS number
        """
        earfcn = 0 if int(earfcn) < 0 else int(earfcn)
        debug_msg = f'Lock EARFCN with earfcn={earfcn}, scs={scs}' if earfcn else 'Unlock Nr EARFCN'
        self.logger.debug(f'At (sub-access): {debug_msg}')
        return self.ue_pc.set_earfcn_lock(ue_id=self.ue_com_port, network_mode=network_mode, earfcn=earfcn,
                                          scs=int(scs), extra_params=kwargs)

    def reset_earfcn_lock(self, network_mode, **kwargs):
        """
        Quectel / Simcom: Reset Lock EARFCN.
        :param network_mode: Network mode for which to lock the earfcn
        """
        return self.ue_pc.reset_earfcn_lock(ue_id=self.ue_com_port, network_mode=network_mode, extra_params=kwargs)

    def _create_voice_call(self, name, definition):
        """
        Create voice call instance.

        :param name: name to be assigned to voice call. You can use it later on as a reference to voice call.
        :param definition: object of VoiceCallDefinition that encapsulates all needed parameters.
        :return: AtVoiceCall instance
        """
        self.logger.debug(f"Creating voice call instance with name {name} started")
        voice_call = AtVoiceCall(vc_name=name, ue_pc=self.ue_pc, ue_name=self.ue_com_port, definition=definition)
        self._voice_call = voice_call
        return voice_call

    def _create_data_transfer(self, name, dt_definition):
        """
        Creating AtIperfDataTransfer object.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: AtIperfDataTransfer instance
        """
        self.logger.debug(f"executing create_data_transfer with name {name} and parameters {dt_definition}")
        dt_config = self.configuration
        requested_protocol = dt_definition.protocol
        tool = self._get_requested_tool(requested_protocol)

        dt_from_uepc = dt_config['data_transfer'][tool].get('dt_from_uepc', False)
        if self._sub_access:
            self.logger.debug(f"sub_access: {self._sub_access}")
            dt_config["sub_access"] = self._sub_access
        self.logger.debug(f"sub_access: {self._sub_access}")

        if dt_from_uepc is True or (dt_from_uepc and strtobool(dt_from_uepc)):
            tool = f"{tool}_uepc"
        if tool == "icmp":
            dt_implementation = self.data_transfer_types.get(tool, AtDataTransferIcmp)
        elif "iperf" in tool:
            dt_implementation = self.data_transfer_types.get(tool, AtIperfUeDataTransfer)
        data_transfer = dt_implementation(name=name, ue_pc=self.ue_pc,
                                          com_port=self.ue_com_port,
                                          dt_definition=dt_definition,
                                          configuration=dt_config)
        scope.current_scope().uses(resource=data_transfer, resource_releaser=self._cleanup_data_transfer)
        return data_transfer

    @staticmethod
    def _get_requested_tool(requested_protocol):
        default_transfer_types = {
            'udp': 'iperf',  # iperf is default tool for udp traffic
            'tcp': 'iperf',  # iperf is default tool for tcp traffic
            'icmp': 'ping',  # ping is default tool for icmp traffic
        }
        return default_transfer_types.get(requested_protocol, 'unknown')

    @staticmethod
    def _cleanup_data_transfer(data_transfer):
        data_transfer.release_resources()

    def _log_ue_pc_diagnostic_info(self):
        raw_logger = logging.getLogger("ute_ue")
        diagnostic_data = requests.get(url=f"{self.ue_pc.remote_url}/about").json()

        warn_about_latest_uepc_libraries_version(raw_logger, {
            "taf.ue.proxy": diagnostic_data.get("version", "0.0.0"),
            "taf.ue.proxy.access.at": self._get_access_plugin_version(diagnostic_data, "at"),
            "taf.ue.proxy.access.quectel": self._get_access_plugin_version(diagnostic_data, "quectel")
        })
        self._check_cygwin_version_compatibility(diagnostic_data.get("cygwin", None))
        robot_logger.info(f"UE {self.ue_com_port} proxy environment: " + str(json.dumps(diagnostic_data,
                                                                                        sort_keys=False,
                                                                                        indent=4)))

    def _check_cygwin_version_compatibility(self, cygwin_version):
        recommended_version = "3.3"
        if cygwin_version:
            if version.parse(cygwin_version) <= version.parse(recommended_version):
                robot_logger.warn(
                    f"The installed Cygwin version {cygwin_version} is lower than the recommended version -"
                    f" {recommended_version}. Consider upgrading Cygwin to avoid potential issues with with moler "
                    "regex prompt."
                )

