    def save_filtered_hdf_file_as_txt(self, hdf_log_file_path, qcat_path=None, filter_path=None, filter_list=None):
        """
        Method for convert HDF file to TXT with filter if needed
        :param hdf_log_file_path str: HDF log file path
        :param qcat_path: str: path to QCAT.exe file
        :param filter_path: str: path to filter file
        :param filter_list: list: list of filters in hex format
        :return: Path to the generated text log file
        """
        qcat_path = qcat_path if qcat_path is not None else self.configuration["qcat_path"]
        self.logger.debug(f"Save filtered HDF file as TXT. Passing parameters: qcat_path: {qcat_path}, "
                          f"hdf_log_file_path: {hdf_log_file_path}, filter_path: {filter_path}, "
                          f"filter_list: {filter_list}")
        return self.ue_pc.save_filtered_hdf_file_as_txt(hdf_log_file_path=hdf_log_file_path, qcat_path=qcat_path,
                                                        filter_path=filter_path, filter_list=filter_list)

    def lock_cell(self, network_mode, pci, arfcn, scs, band, **kwargs):
        """
        Lock Cell on UE
        :param network_mode: Network mode for which to lock the cell (possible: nr, nr5g, 5g, lte, 4g)
        :param pci: PCI number
        :param arfcn: ARFCN number
        :param scs: SCS number 15 - 15kHz, 30 - 30kHz
        :param band: band number
        """
        network_mode = self._parse_network_mode(network_mode)
        debug_msg = f'Lock Cell for {network_mode} with pci={pci}, arfcn={arfcn}, scs={scs}, band={band}'
        self.logger.debug(f'At (sub-access): {debug_msg}')
        extra_params = {
            "scs": scs,
            "band": band
        }
        return self.ue_pc.lock_cell(ue_id=self.ue_com_port, network_mode=network_mode, pci=pci, arfcn=arfcn,
                                    extra_params=extra_params)

    def unlock_cell(self, network_mode, **kwargs):
        """
        Unlock Cell on UE
        :param network_mode: Network mode for which to unlock the earfcn (possible: nr, nr5g, 5g, lte, 4g)
        """
        network_mode = self._parse_network_mode(network_mode)
        debug_msg = f'Unlock Cell for {network_mode}'
        self.logger.debug(f'At (sub-access): {debug_msg}')
        return self.ue_pc.unlock_cell(ue_id=self.ue_com_port, network_mode=network_mode)

    def _parse_network_mode(self, network_mode):
        if network_mode.lower() in ('nr', '5g', 'nr5g'):
            network_mode = 'nr'
        elif network_mode.lower() in ('lte', '4g'):
            network_mode = 'lte'
        else:
            raise NotImplementedError(f"Network mode: {network_mode} is not supported")
        return network_mode

    @staticmethod
    def _get_access_plugin_version(diagnostic_data, access_plugin):
        """
        Get plugin version from diagnostic data
        """
        for key, value in diagnostic_data.items():
            if 'plugin' in key and access_plugin in value.get("name", "").lower():
                return value.get("details", {}).get("version", "0.0.0")
        return "0.0.0"
